CtoF <- function(celsius) {
  celsius * (9/5) + 32
}
CtoF(27)## [1] 80.6

## explicit return
CtoFexp <- function(celsius) {
  fahrenheit <- celsius * (9/5) + 32
  return(fahrenheit)
}

CtoFexp(27)## [1] 80.6

CtoFrounded <- function(celsius, decimals = 0) {
  fahrenheit <- celsius * (9/5) + 32
  round(fahrenheit, decimals)
}

CtoFrounded(27)## [1] 81
CtoFrounded(celsius = 27, decimals = 1)## [1] 80.6
CtoFrounded(27, 1)## [1] 80.6
CtoFrounded(decimals = 1, celsius = 27)## [1] 80.6
CtoFnodef <- function(celsius, decimals) {
